    for (let i = W - 1; i >= 0; i--) { const w = a[i]; dn[i] = (w >>> 1) | (carry << 31); carry = w & 1; }
    for (let i = 0; i < W; i++) b[i] = up[i] ^ (a[i] | dn[i]);
    const tmp = a; a = b; b = tmp;
  }
